function json(data, status) {
  return new Response(JSON.stringify(data), {
    status: status || 200,
    headers: { 'content-type': 'application/json; charset=utf-8' },
  });
}

function uid(prefix) {
  return (prefix || 'id') + '_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
}

function settingsRowToObj(row) {
  return {
    companyName: row.company_name,
    companyLogo: row.company_logo,
    companyPhone: row.company_phone,
    companyEmail: row.company_email,
    companyCnpj: row.company_cnpj,
    companyAddress: row.company_address,
    defaultMargin: row.default_margin,
    defaultMarkup: row.default_markup,
    defaultTaxes: row.default_taxes,
    defaultCardFee: row.default_card_fee,
    defaultEnergyPrice: row.default_energy_price,
    budgetSeq: row.budget_seq,
    orderSeq: row.order_seq,
  };
}

async function getSettings(db) {
  const row = await db.prepare('SELECT * FROM settings WHERE id = 1').first();
  return settingsRowToObj(row);
}

async function getFilaments(db) {
  const { results } = await db.prepare('SELECT * FROM filaments ORDER BY sort_order ASC, name ASC').all();
  return results.map((f) => ({ id: f.id, name: f.name, category: f.category, price: f.price, extrusion: f.extrusion, bed: f.bed, desc: f.desc, color: f.color || '' }));
}
async function getFilamentPriceHistory(db, filamentId) {
  const { results } = await db.prepare('SELECT * FROM filament_price_history WHERE filament_id=? ORDER BY created_at DESC, rowid DESC').bind(filamentId).all();
  return results.map((r) => ({ id: r.id, price: r.price, createdAt: r.created_at }));
}
/* Registra um novo valor de preço no histórico do filamento e recalcula o
   preço "atual" como a MÉDIA de todos os valores já registrados para ele. */
async function recordFilamentPrice(db, filamentId, price) {
  await db.prepare('INSERT INTO filament_price_history (id, filament_id, price) VALUES (?,?,?)').bind(uid('fph'), filamentId, price).run();
  const row = await db.prepare('SELECT AVG(price) as avg FROM filament_price_history WHERE filament_id=?').bind(filamentId).first();
  return Math.round((row && row.avg ? row.avg : price) * 100) / 100;
}

