/* ==========================================================================
   Autenticação — login com Conta Google, sem senha própria.
   Só entra quem tiver o e-mail cadastrado em authorized_emails. A sessão
   (token opaco, só o hash fica salvo no banco) expira depois de 8h SEM uso
   — cada requisição autenticada "desliza" o prazo para frente.
   ========================================================================== */
const GOOGLE_CLIENT_ID = '227244385059-u4dopuog1v2sjlt5s8qebi6gv62nheqq.apps.googleusercontent.com';
const GOOGLE_JWKS_URL = 'https://www.googleapis.com/oauth2/v3/certs';
const SESSION_TTL_MS = 8 * 60 * 60 * 1000;

function bytesToHex(bytes) {
  return Array.from(bytes).map((b) => b.toString(16).padStart(2, '0')).join('');
}
function b64urlToBytes(b64url) {
  const b64 = b64url.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((b64url.length + 3) % 4);
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
function b64urlToJson(b64url) {
  return JSON.parse(new TextDecoder().decode(b64urlToBytes(b64url)));
}
async function sha256Hex(str) {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(str));
  return bytesToHex(new Uint8Array(buf));
}
function generateToken() {
  return bytesToHex(crypto.getRandomValues(new Uint8Array(32)));
}

/* Verifica um ID token (JWT) emitido pelo Google Identity Services: assinatura
   RS256 contra as chaves públicas do Google, validade, emissor, client id
   (aud) e e-mail verificado. `fetchJwks` é injetável (usado nos testes, para
   não depender de bater no Google de verdade). Lança Error com mensagem
   amigável quando algo não confere. */
export async function verifyGoogleIdToken(idToken, fetchJwks) {
  const parts = (idToken || '').split('.');
  if (parts.length !== 3) throw new Error('Token do Google inválido.');
  const [headerB64, payloadB64, sigB64] = parts;
  let header, payload;
  try {
    header = b64urlToJson(headerB64);
    payload = b64urlToJson(payloadB64);
  } catch (e) {
    throw new Error('Token do Google inválido.');
  }
  if (header.alg !== 'RS256') throw new Error('Token do Google com algoritmo inesperado.');

  const doFetch = fetchJwks || (() => fetch(GOOGLE_JWKS_URL).then((r) => r.json()));
  const jwks = await doFetch();
  const jwk = (jwks.keys || []).find((k) => k.kid === header.kid);
  if (!jwk) throw new Error('Não foi possível validar a assinatura do Google (chave não encontrada).');

  const key = await crypto.subtle.importKey('jwk', jwk, { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['verify']);
  const signedData = new TextEncoder().encode(`${headerB64}.${payloadB64}`);
  const signature = b64urlToBytes(sigB64);
  const ok = await crypto.subtle.verify('RSASSA-PKCS1-v1_5', key, signature, signedData);
  if (!ok) throw new Error('Assinatura do token do Google inválida.');

  const now = Math.floor(Date.now() / 1000);
  if (typeof payload.exp !== 'number' || payload.exp < now) throw new Error('Token do Google expirado, tente entrar de novo.');
  if (payload.aud !== GOOGLE_CLIENT_ID) throw new Error('Token do Google não é para este aplicativo.');
  if (payload.iss !== 'https://accounts.google.com' && payload.iss !== 'accounts.google.com') {
    throw new Error('Emissor do token do Google inválido.');
  }
  if (!payload.email || payload.email_verified !== true) throw new Error('Seu e-mail do Google não está verificado.');

  return { email: String(payload.email).toLowerCase(), name: payload.name || payload.email };
}

async function isEmailAuthorized(db, email) {
  return await db.prepare('SELECT email, name FROM authorized_emails WHERE LOWER(email) = LOWER(?)').bind(email).first();
}

async function createSession(db, email, name) {
  const token = generateToken();
  const tokenHash = await sha256Hex(token);
  const now = new Date().toISOString();
  await db.prepare('INSERT INTO sessions (token_hash, email, name, created_at, last_seen_at) VALUES (?,?,?,?,?)')
    .bind(tokenHash, email, name, now, now).run();
  return token;
}

/* Exige Authorization: Bearer <token> válido e não expirado por 8h de
   inatividade — e desliza o prazo (last_seen_at) a cada chamada. */
async function requireSession(db, request) {
  const authHeader = request.headers.get('authorization') || '';
  const m = authHeader.match(/^Bearer\s+(.+)$/i);
  if (!m) return { error: 'Não autenticado. Faça login.', code: 'NO_TOKEN', status: 401 };
  const token = m[1].trim();
  const tokenHash = await sha256Hex(token);
  const row = await db.prepare('SELECT * FROM sessions WHERE token_hash=?').bind(tokenHash).first();
  if (!row) return { error: 'Sessão inválida. Faça login novamente.', code: 'SESSION_EXPIRED', status: 401 };
  const lastSeen = new Date(row.last_seen_at).getTime();
  if (!isFinite(lastSeen) || Date.now() - lastSeen > SESSION_TTL_MS) {
    await db.prepare('DELETE FROM sessions WHERE token_hash=?').bind(tokenHash).run();
    return { error: 'Sua sessão expirou por inatividade. Faça login novamente.', code: 'SESSION_EXPIRED', status: 401 };
  }
  await db.prepare('UPDATE sessions SET last_seen_at=? WHERE token_hash=?').bind(new Date().toISOString(), tokenHash).run();
  return { user: { email: row.email, name: row.name }, tokenHash };
}

async function getAuthorizedEmails(db) {
  const { results } = await db.prepare('SELECT email, name, added_at as addedAt FROM authorized_emails ORDER BY name ASC, email ASC').all();
  return results;
}

export async function handleApi(request, env, url) {
  const db = env.DB;
  if (!db) return json({ error: 'Banco de dados não configurado (binding DB ausente).' }, 500);
  const { pathname } = url;
  const method = request.method;

  // ---- Login (não exige sessão) ----
  if (pathname === '/api/auth/google' && method === 'POST') {
    let body;
    try { body = await request.json(); } catch (e) { return json({ error: 'Requisição inválida.' }, 400); }
    let googleUser;
    try {
      googleUser = await verifyGoogleIdToken(body.credential);
    } catch (e) {
      return json({ error: e.message || 'Não foi possível validar o login do Google.' }, 401);
    }
    const authorized = await isEmailAuthorized(db, googleUser.email);
    if (!authorized) {
      return json({
        error: `O e-mail ${googleUser.email} não está autorizado a acessar este sistema. Peça para um administrador liberar seu acesso em Configurações → Usuários autorizados.`,
        code: 'NOT_AUTHORIZED',
      }, 403);
    }
    const name = authorized.name || googleUser.name || googleUser.email;
    const token = await createSession(db, googleUser.email, name);
    return json({ token, user: { email: googleUser.email, name } });
  }

  // ---- A partir daqui, todas as rotas exigem sessão válida ----
  const auth = await requireSession(db, request);
  if (auth.error) return json({ error: auth.error, code: auth.code }, auth.status);
  const currentUser = auth.user;
  let m; // reutilizado pelas rotas com :id abaixo

  if (pathname === '/api/auth/logout' && method === 'POST') {
    await db.prepare('DELETE FROM sessions WHERE token_hash=?').bind(auth.tokenHash).run();
    return json({ ok: true });
  }
  if (pathname === '/api/auth/me' && method === 'GET') {
    return json({ email: currentUser.email, name: currentUser.name });
  }

  // ---- Usuários autorizados a entrar com Google ----
  if (pathname === '/api/authorized-emails' && method === 'GET') return json(await getAuthorizedEmails(db));
  if (pathname === '/api/authorized-emails' && method === 'POST') {
    const b = await request.json();
    const email = (b.email || '').trim().toLowerCase();
    const name = (b.name || '').trim();
    if (!email || !email.includes('@')) return json({ error: 'Informe um e-mail do Google válido.', field: 'email' }, 400);
    if (!name) return json({ error: 'Informe o nome da pessoa.', field: 'name' }, 400);
    await db.prepare('INSERT INTO authorized_emails (email, name) VALUES (?,?) ON CONFLICT(email) DO UPDATE SET name=excluded.name')
      .bind(email, name).run();
    return json(await getAuthorizedEmails(db));
  }
  m = pathname.match(/^\/api\/authorized-emails\/([^/]+)$/);
  if (m && method === 'DELETE') {
    const targetEmail = decodeURIComponent(m[1]).toLowerCase();
    if (targetEmail === currentUser.email.toLowerCase()) {
      return json({ error: 'Você não pode remover seu próprio acesso enquanto estiver logado com ele.' }, 400);
    }
    const countRow = await db.prepare('SELECT COUNT(*) as c FROM authorized_emails').first();
    if (countRow.c <= 1) return json({ error: 'Não é possível remover o último usuário autorizado — ninguém mais conseguiria entrar.' }, 400);
    await db.prepare('DELETE FROM authorized_emails WHERE LOWER(email)=?').bind(targetEmail).run();
    await db.prepare('DELETE FROM sessions WHERE LOWER(email)=?').bind(targetEmail).run();
    return json(await getAuthorizedEmails(db));
  }

  // ---- Estado inicial combinado ----
  if (pathname === '/api/state' && method === 'GET') {
    const [settings, filaments, printers, packagingTypes, resolutions, history, sales, orders, purchases, products, people, colors] = await Promise.all([
      getSettings(db), getFilaments(db), getPrinters(db), getPackagingTypes(db), getResolutions(db), getHistory(db), getSales(db), getOrders(db), getPurchases(db), getProducts(db), getPeople(db), getColors(db),
    ]);
    return json({ settings, filaments, printers, packagingTypes, resolutions, history, sales, orders, purchases, products, people, colors });
  }

  // ---- Configurações / empresa ----
  if (pathname === '/api/settings' && method === 'GET') return json(await getSettings(db));
  if (pathname === '/api/settings' && method === 'PUT') {
    const body = await request.json();
    const cur = await db.prepare('SELECT * FROM settings WHERE id = 1').first();
    const merged = {
      company_name: body.companyName ?? cur.company_name,
      company_logo: body.companyLogo ?? cur.company_logo,
      company_phone: body.companyPhone ?? cur.company_phone,
      company_email: body.companyEmail ?? cur.company_email,
      company_cnpj: body.companyCnpj ?? cur.company_cnpj,
      company_address: body.companyAddress ?? cur.company_address,
      default_margin: body.defaultMargin ?? cur.default_margin,
      default_markup: body.defaultMarkup ?? cur.default_markup,
      default_taxes: body.defaultTaxes ?? cur.default_taxes,
      default_card_fee: body.defaultCardFee ?? cur.default_card_fee,
      default_energy_price: body.defaultEnergyPrice ?? cur.default_energy_price,
    };
    await db.prepare(
      `UPDATE settings SET company_name=?, company_logo=?, company_phone=?, company_email=?, company_cnpj=?, company_address=?,
       default_margin=?, default_markup=?, default_taxes=?, default_card_fee=?, default_energy_price=?, updated_at=datetime('now') WHERE id=1`
    ).bind(
      merged.company_name, merged.company_logo, merged.company_phone, merged.company_email, merged.company_cnpj, merged.company_address,
      merged.default_margin, merged.default_markup, merged.default_taxes, merged.default_card_fee, merged.default_energy_price
    ).run();
    return json(await getSettings(db));
  }

  if (pathname === '/api/settings/restore-defaults' && method === 'POST') {
    await db.prepare(
      `UPDATE settings SET company_name='DB Criações 3D', company_logo='', company_phone='', company_email='', company_cnpj='', company_address='',
       default_margin=5, default_markup=30, default_taxes=0, default_card_fee=0, default_energy_price=0.95, updated_at=datetime('now') WHERE id=1`
    ).run();
    return json(await getSettings(db));
  }

  if (pathname === '/api/settings/next-budget-number' && method === 'POST') {
    await db.prepare("UPDATE settings SET budget_seq = budget_seq + 1, updated_at=datetime('now') WHERE id = 1").run();
    const row = await db.prepare('SELECT budget_seq FROM settings WHERE id = 1').first();
    return json({ budgetSeq: row.budget_seq });
  }

  if (pathname === '/api/settings/next-order-number' && method === 'POST') {
    await db.prepare("UPDATE settings SET order_seq = order_seq + 1, updated_at=datetime('now') WHERE id = 1").run();
    const row = await db.prepare('SELECT order_seq FROM settings WHERE id = 1').first();
    return json({ orderSeq: row.order_seq });
  }

  // ---- Filamentos ----
  if (pathname === '/api/filaments' && method === 'GET') return json(await getFilaments(db));
  let mph = pathname.match(/^\/api\/filaments\/([^/]+)\/price-history$/);
  if (mph && method === 'GET') return json(await getFilamentPriceHistory(db, mph[1]));
  if (pathname === '/api/filaments' && method === 'POST') {
    const b = await request.json();
    const id = uid('fil');
    const price = Number(b.price) || 0;
    await db.prepare('INSERT INTO filaments (id, name, category, price, extrusion, bed, desc, color, sort_order) VALUES (?,?,?,?,?,?,?,?,999)')
      .bind(id, b.name || 'Sem nome', b.category || 'Especial', price, Number(b.extrusion) || 0, Number(b.bed) || 0, b.desc || 'Preset personalizado', b.color || '').run();
    // Primeiro valor de preço já entra no histórico (a média de 1 valor é ele mesmo).
    await recordFilamentPrice(db, id, price);
    return json(await getFilaments(db));
  }
  m = pathname.match(/^\/api\/filaments\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    const cur = await db.prepare('SELECT price FROM filaments WHERE id=?').bind(m[1]).first();
    const typedPrice = Number(b.price) || 0;
    // Só registra no histórico (e recalcula a média) quando o valor digitado
    // é de fato NOVO — evita inflar a média ao salvar sem mexer no preço.
    const isNewValue = !cur || Math.round(typedPrice * 100) !== Math.round((cur.price || 0) * 100);
    const finalPrice = isNewValue ? await recordFilamentPrice(db, m[1], typedPrice) : (cur ? cur.price : typedPrice);
    await db.prepare('UPDATE filaments SET name=?, category=?, price=?, extrusion=?, bed=?, desc=?, color=? WHERE id=?')
      .bind(b.name, b.category || 'Especial', finalPrice, Number(b.extrusion) || 0, Number(b.bed) || 0, b.desc || '', b.color || '', m[1]).run();
    return json(await getFilaments(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM filament_price_history WHERE filament_id=?').bind(m[1]).run();
    await db.prepare('DELETE FROM filaments WHERE id=?').bind(m[1]).run();
    return json(await getFilaments(db));
  }

  // ---- Impressoras ----
  if (pathname === '/api/printers' && method === 'GET') return json(await getPrinters(db));
  if (pathname === '/api/printers' && method === 'POST') {
    const b = await request.json();
    const id = uid('prt');
    await db.prepare('INSERT INTO printers (id, name, category, power, depreciation, desc, sort_order) VALUES (?,?,?,?,?,?,999)')
      .bind(id, b.name || 'Sem nome', b.category || 'FDM Intermediária', Number(b.power) || 0, Number(b.depreciation) || 0, b.desc || 'Preset personalizado').run();
    return json(await getPrinters(db));
  }
  m = pathname.match(/^\/api\/printers\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare('UPDATE printers SET name=?, category=?, power=?, depreciation=?, desc=? WHERE id=?')
      .bind(b.name, b.category || 'FDM Intermediária', Number(b.power) || 0, Number(b.depreciation) || 0, b.desc || '', m[1]).run();
    return json(await getPrinters(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM printers WHERE id=?').bind(m[1]).run();
    return json(await getPrinters(db));
  }

  // ---- Tipos de embalagem ----
  if (pathname === '/api/packaging-types' && method === 'GET') return json(await getPackagingTypes(db));
  if (pathname === '/api/packaging-types' && method === 'POST') {
    const b = await request.json();
    const id = uid('pkg');
    await db.prepare('INSERT INTO packaging_types (id, label, sort_order) VALUES (?,?,999)').bind(id, b.label || 'Sem nome').run();
    return json(await getPackagingTypes(db));
  }
  m = pathname.match(/^\/api\/packaging-types\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare('UPDATE packaging_types SET label=? WHERE id=?').bind(b.label, m[1]).run();
    return json(await getPackagingTypes(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM packaging_types WHERE id=?').bind(m[1]).run();
    return json(await getPackagingTypes(db));
  }

  // ---- Resoluções ----
  if (pathname === '/api/resolutions' && method === 'GET') return json(await getResolutions(db));
  if (pathname === '/api/resolutions' && method === 'POST') {
    const b = await request.json();
    const id = uid('res');
    await db.prepare('INSERT INTO resolutions (id, value_mm, label, sort_order) VALUES (?,?,?,999)').bind(id, Number(b.v) || 0, b.l || 'Sem nome').run();
    return json(await getResolutions(db));
  }
  m = pathname.match(/^\/api\/resolutions\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare('UPDATE resolutions SET value_mm=?, label=? WHERE id=?').bind(Number(b.v) || 0, b.l, m[1]).run();
    return json(await getResolutions(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM resolutions WHERE id=?').bind(m[1]).run();
    return json(await getResolutions(db));
  }

  // ---- Orçamentos (histórico de cálculos) ----
  if (pathname === '/api/history' && method === 'GET') return json(await getHistory(db));
  if (pathname === '/api/history' && method === 'POST') {
    const b = await request.json();
    const id = b.id || uid('hist');
    await db.prepare('INSERT INTO history (id, saved_at, name, calc_json, result_json, budget_number) VALUES (?,?,?,?,?,?)')
      .bind(id, b.savedAt || new Date().toISOString(), b.name || 'Sem nome', JSON.stringify(b.calc || {}), JSON.stringify(b.result || {}), b.budgetNumber || '').run();
    return json(await getHistory(db));
  }
  if (pathname === '/api/history' && method === 'DELETE') {
    await db.prepare('DELETE FROM history').run();
    return json([]);
  }
  m = pathname.match(/^\/api\/history\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare('UPDATE history SET name=?, calc_json=?, result_json=?, budget_number=? WHERE id=?')
      .bind(b.name || 'Sem nome', JSON.stringify(b.calc || {}), JSON.stringify(b.result || {}), b.budgetNumber || '', m[1]).run();
    return json(await getHistory(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM history WHERE id=?').bind(m[1]).run();
    return json(await getHistory(db));
  }

  // ---- Vendas ----
  if (pathname === '/api/sales' && method === 'GET') return json(await getSales(db));
  if (pathname === '/api/sales' && method === 'POST') {
    const b = await request.json();
    const id = uid('sale');
    await db.prepare(
      `INSERT INTO sales (id, date, source, history_id, order_id, project_name, client_name, amount, items_json, extra_costs_json, shipping_value, notes, payment_method)
       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`
    ).bind(
      id, b.date || new Date().toISOString().slice(0, 10), b.source || 'manual', b.historyId || '', b.orderId || '',
      b.projectName || '', b.clientName || '', Number(b.amount) || 0, JSON.stringify(Array.isArray(b.items) ? b.items : []),
      JSON.stringify(Array.isArray(b.extraCosts) ? b.extraCosts : []), Number(b.shippingValue) || 0, b.notes || '', b.paymentMethod || ''
    ).run();
    return json(await getSales(db));
  }
  m = pathname.match(/^\/api\/sales\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare(
      `UPDATE sales SET date=?, project_name=?, client_name=?, amount=?, items_json=?, extra_costs_json=?, shipping_value=?, notes=?, payment_method=? WHERE id=?`
    ).bind(
      b.date || new Date().toISOString().slice(0, 10), b.projectName || '', b.clientName || '',
      Number(b.amount) || 0, JSON.stringify(Array.isArray(b.items) ? b.items : []),
      JSON.stringify(Array.isArray(b.extraCosts) ? b.extraCosts : []), Number(b.shippingValue) || 0, b.notes || '', b.paymentMethod || '', m[1]
    ).run();
    return json(await getSales(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM sales WHERE id=?').bind(m[1]).run();
    return json(await getSales(db));
  }

  // ---- Pedidos (fila de pedidos — controle de ordem de atendimento) ----
  if (pathname === '/api/orders' && method === 'GET') return json(await getOrders(db));
  if (pathname === '/api/orders' && method === 'POST') {
    const b = await request.json();
    const id = uid('order');
    await db.prepare(
      `INSERT INTO orders (id, order_number, date, source, history_id, status, project_name, client_name, amount, items_json, extra_costs_json, shipping_value, notes, payment_method)
       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`
    ).bind(
      id, b.orderNumber || '', b.date || new Date().toISOString().slice(0, 10), b.source || 'manual', b.historyId || '',
      b.status || 'aberto', b.projectName || '', b.clientName || '', Number(b.amount) || 0,
      JSON.stringify(Array.isArray(b.items) ? b.items : []), JSON.stringify(Array.isArray(b.extraCosts) ? b.extraCosts : []),
      Number(b.shippingValue) || 0, b.notes || '', b.paymentMethod || ''
    ).run();
    return json(await getOrders(db));
  }
  m = pathname.match(/^\/api\/orders\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare(
      `UPDATE orders SET date=?, status=?, project_name=?, client_name=?, amount=?, items_json=?, extra_costs_json=?, shipping_value=?, notes=?, payment_method=? WHERE id=?`
    ).bind(
      b.date || new Date().toISOString().slice(0, 10), b.status || 'aberto', b.projectName || '', b.clientName || '',
      Number(b.amount) || 0, JSON.stringify(Array.isArray(b.items) ? b.items : []),
      JSON.stringify(Array.isArray(b.extraCosts) ? b.extraCosts : []), Number(b.shippingValue) || 0, b.notes || '', b.paymentMethod || '', m[1]
    ).run();
    return json(await getOrders(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM orders WHERE id=?').bind(m[1]).run();
    return json(await getOrders(db));
  }

  // ---- Compras ----
  if (pathname === '/api/purchases' && method === 'GET') return json(await getPurchases(db));
  if (pathname === '/api/purchases' && method === 'POST') {
    const b = await request.json();
    const id = uid('pur');
    await db.prepare(
      'INSERT INTO purchases (id, date, description, category, supplier, amount, payment_method, notes) VALUES (?,?,?,?,?,?,?,?)'
    ).bind(
      id, b.date || new Date().toISOString().slice(0, 10), b.description || '', b.category || 'Outros',
      b.supplier || '', Number(b.amount) || 0, b.paymentMethod || '', b.notes || ''
    ).run();
    return json(await getPurchases(db));
  }
  m = pathname.match(/^\/api\/purchases\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare(
      'UPDATE purchases SET date=?, description=?, category=?, supplier=?, amount=?, payment_method=?, notes=? WHERE id=?'
    ).bind(
      b.date || new Date().toISOString().slice(0, 10), b.description || '', b.category || 'Outros',
      b.supplier || '', Number(b.amount) || 0, b.paymentMethod || '', b.notes || '', m[1]
    ).run();
    return json(await getPurchases(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM purchases WHERE id=?').bind(m[1]).run();
    return json(await getPurchases(db));
  }

  // ---- Cadastro de Produtos ----
  if (pathname === '/api/products' && method === 'GET') return json(await getProducts(db));
  if (pathname === '/api/products' && method === 'POST') {
    const b = await request.json();
    const id = uid('prod');
    await db.prepare(
      `INSERT INTO products (id, name, dimensions, color, finish, nozzle, resolution, filament_name, filament_price,
        piece_weight, printer_name, printer_power, print_time, depreciation, photo, extra_costs_json, price, notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`
    ).bind(
      id, b.name || 'Sem nome', b.dimensions || '', b.color || '', b.finish || 'Bruto',
      Number(b.nozzle) || 0.4, Number(b.resolution) || 0.2, b.filamentName || '', Number(b.filamentPrice) || 0,
      Number(b.pieceWeight) || 0, b.printerName || '', Number(b.printerPower) || 0, Number(b.printTime) || 0,
      Number(b.depreciation) || 0, b.photo || '', JSON.stringify(Array.isArray(b.extraCosts) ? b.extraCosts : []),
      Number(b.price) || 0, b.notes || ''
    ).run();
    return json(await getProducts(db));
  }
  m = pathname.match(/^\/api\/products\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare(
      `UPDATE products SET name=?, dimensions=?, color=?, finish=?, nozzle=?, resolution=?, filament_name=?, filament_price=?,
        piece_weight=?, printer_name=?, printer_power=?, print_time=?, depreciation=?, photo=?, extra_costs_json=?, price=?, notes=? WHERE id=?`
    ).bind(
      b.name || 'Sem nome', b.dimensions || '', b.color || '', b.finish || 'Bruto',
      Number(b.nozzle) || 0.4, Number(b.resolution) || 0.2, b.filamentName || '', Number(b.filamentPrice) || 0,
      Number(b.pieceWeight) || 0, b.printerName || '', Number(b.printerPower) || 0, Number(b.printTime) || 0,
      Number(b.depreciation) || 0, b.photo || '', JSON.stringify(Array.isArray(b.extraCosts) ? b.extraCosts : []),
      Number(b.price) || 0, b.notes || '', m[1]
    ).run();
    return json(await getProducts(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM products WHERE id=?').bind(m[1]).run();
    return json(await getProducts(db));
  }

  // ---- Cadastro de Pessoas ----
  if (pathname === '/api/people' && method === 'GET') return json(await getPeople(db));
  if (pathname === '/api/people' && method === 'POST') {
    const b = await request.json();
    const id = uid('person');
    await db.prepare('INSERT INTO people (id, name, cpf, phone, address, email, notes) VALUES (?,?,?,?,?,?,?)')
      .bind(id, b.name || 'Sem nome', b.cpf || '', b.phone || '', b.address || '', b.email || '', b.notes || '').run();
    return json(await getPeople(db));
  }
  m = pathname.match(/^\/api\/people\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare('UPDATE people SET name=?, cpf=?, phone=?, address=?, email=?, notes=? WHERE id=?')
      .bind(b.name || 'Sem nome', b.cpf || '', b.phone || '', b.address || '', b.email || '', b.notes || '', m[1]).run();
    return json(await getPeople(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM people WHERE id=?').bind(m[1]).run();
    return json(await getPeople(db));
  }

  // ---- Cores (cadastradas conforme os orçamentos são salvos, editável em Configurações) ----
  if (pathname === '/api/colors' && method === 'GET') return json(await getColors(db));
  if (pathname === '/api/colors' && method === 'POST') {
    const b = await request.json();
    const name = (b.name || '').trim();
    if (name) {
      const existing = await db.prepare('SELECT id FROM colors WHERE LOWER(name) = LOWER(?)').bind(name).first();
      if (!existing) {
        await db.prepare('INSERT INTO colors (id, name) VALUES (?, ?)').bind(uid('color'), name).run();
      }
    }
    return json(await getColors(db));
  }
  m = pathname.match(/^\/api\/colors\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    const name = (b.name || '').trim();
    if (name) await db.prepare('UPDATE colors SET name=? WHERE id=?').bind(name, m[1]).run();
    return json(await getColors(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM colors WHERE id=?').bind(m[1]).run();
    return json(await getColors(db));
  }

  return json({ error: 'Rota não encontrada' }, 404);
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname.startsWith('/api/')) {
      try {
        return await handleApi(request, env, url);
      } catch (err) {
        return new Response(JSON.stringify({ error: String((err && err.message) || err) }), {
          status: 500,
          headers: { 'content-type': 'application/json; charset=utf-8' },
        });
      }
    }
    return new Response(APP_HTML, { headers: { 'content-type': 'text/html; charset=utf-8' } });
  },
};
